/* Direct-NUP runtime parser/read test. The package is generated by tests/run_nup.sh. */
#include "rt.h"
#include <sys/stat.h>
#include <unistd.h>

int plat_pread(FILE* file,void* data,u64 size,u64 offset){ return (int)pread(fileno(file),data,(size_t)size,(off_t)offset); }
u64 plat_file_size(const char* path){ struct stat info; return stat(path,&info)?0:(u64)info.st_size; }

static u32 find_entry(Nup* n,const char* path){
  u32 current=0; const char* part=path;
  while(*part){ const char* end=strchr(part,'/'); u32 want=(u32)(end?(size_t)(end-part):strlen(part));
    u32 first=0,count=0; if(nup_children(n,current,&first,&count)) return 0xFFFFFFFFu; u32 found=0xFFFFFFFFu;
    for(u32 k=0;k<count;k++){ u32 length=0; const char* name=nup_name(n,first+k,&length);
      if(length==want && !memcmp(name,part,want)){ found=first+k; break; } }
    if(found==0xFFFFFFFFu) return found; current=found; if(!end) break; part=end+1;
  }
  return current;
}

int main(int argc,char** argv){
  if(argc!=2){ fprintf(stderr,"usage: test_nup_runtime package.nup\n"); return 2; }
  Nup* n=nup_open(argv[1]); if(!n){ fprintf(stderr,"FAIL open\n"); return 1; }
  u32 raw=find_entry(n,"Data/raw.bin"),packed=find_entry(n,"Data/packed.bin");
  if(raw==0xFFFFFFFFu || packed==0xFFFFFFFFu || nup_file_size(n,raw)!=8 || nup_file_size(n,packed)!=256u*1024u){ fprintf(stderr,"FAIL tree\n"); return 1; }
  char text[8]; if(nup_pread(n,raw,text,sizeof text,0) || memcmp(text,"raw data",8)){ fprintf(stderr,"FAIL raw\n"); return 1; }
  u8* data=malloc(256u*1024u); if(!data || nup_pread(n,packed,data,256u*1024u,0)){ fprintf(stderr,"FAIL zstd read\n"); return 1; }
  for(u32 i=0;i<256u*1024u;i++) if(data[i]!=(u8)i){ fprintf(stderr,"FAIL zstd data at %u\n",i); return 1; }
  free(data); nup_close(n); puts("PASS direct NUP runtime reads"); return 0;
}
